import random
random.seed(5)
for _ in range(1000):
    xs = [random.randint(-5, 5) for _ in range(4)]
    if xs and min(xs) != sorted(xs)[0]:
        print('counterexample (impossible here)'); break
else:
    print('1000 fuzz cases: property held (no counterexample)')

